import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"インスタント機能とキーワード拡張","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. プレフィックス不要の即時機能","slug":"_1-プレフィックス不要の即時機能","link":"#_1-プレフィックス不要の即時機能","children":[{"level":3,"title":"計算機と基数変換","slug":"計算機と基数変換","link":"#計算機と基数変換","children":[]},{"level":3,"title":"環境変数の展開と検索","slug":"環境変数の展開と検索","link":"#環境変数の展開と検索","children":[]},{"level":3,"title":"コマンドの直接実行","slug":"コマンドの直接実行","link":"#コマンドの直接実行","children":[]},{"level":3,"title":"Web サイトの URL 直開き","slug":"web-サイトの-url-直開き","link":"#web-サイトの-url-直開き","children":[]},{"level":3,"title":"クイック検索ウィンドウへのクリップボード文字列の取り込み","slug":"クイック検索ウィンドウへのクリップボード文字列の取り込み","link":"#クイック検索ウィンドウへのクリップボード文字列の取り込み","children":[]}]},{"level":2,"title":"2. キーワード起動機能（内蔵プラグイン）","slug":"_2-キーワード起動機能-内蔵プラグイン","link":"#_2-キーワード起動機能-内蔵プラグイン","children":[]},{"level":2,"title":"3. Web 検索エンジン連携","slug":"_3-web-検索エンジン連携","link":"#_3-web-検索エンジン連携","children":[]},{"level":2,"title":"4. インスタント翻訳","slug":"_4-インスタント翻訳","link":"#_4-インスタント翻訳","children":[]},{"level":2,"title":"5. ファイルフィルター","slug":"_5-ファイルフィルター","link":"#_5-ファイルフィルター","children":[]},{"level":2,"title":"6. カスタムコマンド","slug":"_6-カスタムコマンド","link":"#_6-カスタムコマンド","children":[]}],"relativePath":"ja-JP/user-guide/instant-answers.md","filePath":"ja-JP/user-guide/instant-answers.md","lastUpdated":1791210112000}`),a={name:`ja-JP/user-guide/instant-answers.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="インスタント機能とキーワード拡張" tabindex="-1">インスタント機能とキーワード拡張 <a class="header-anchor" href="#インスタント機能とキーワード拡張" aria-label="Permalink to “インスタント機能とキーワード拡張”">​</a></h1><p>Lertaro はローカルファイルの検索だけでなく、即座に計算結果を返す機能や各種システムツール、キーワード連動型の拡張プラグインを標準搭載しています。ファイル検索の完了を待つことなく、コマンドを入力するだけで即座に結果を得られます。</p><h2 id="_1-プレフィックス不要の即時機能" tabindex="-1">1. プレフィックス不要の即時機能 <a class="header-anchor" href="#_1-プレフィックス不要の即時機能" aria-label="Permalink to “1. プレフィックス不要の即時機能”">​</a></h2><p>キーワードを入力しなくても、入力した文字列が特定のパターンに一致すると自動的に起動します。</p><h3 id="計算機と基数変換" tabindex="-1">計算機と基数変換 <a class="header-anchor" href="#計算機と基数変換" aria-label="Permalink to “計算機と基数変換”">​</a></h3><p>検索ボックスに計算式を直接入力すると、計算結果が 1 行目にリアルタイムで表示されます。<code>Enter</code> キーを押すと計算結果がクリップボードにコピーされます。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>進数変換にも標準で対応しています。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="環境変数の展開と検索" tabindex="-1">環境変数の展開と検索 <a class="header-anchor" href="#環境変数の展開と検索" aria-label="Permalink to “環境変数の展開と検索”">​</a></h3><ul><li><strong>変数の展開</strong>：<code>%NAME%</code>（例: <code>%PATH%</code>、<code>%APPDATA%</code>）を入力すると、変数の実際の値が表示されます。<code>PATH</code> などの複数のパスを含む変数は、見やすいリスト形式に自動展開されます。</li><li><strong>変数のあいまい検索</strong>：<code>%</code> に続けてキーワードを入力する（例: <code>%temp</code>）と、名前にその文字を含むシステム/ユーザー環境変数を検索できます。</li></ul><h3 id="コマンドの直接実行" tabindex="-1">コマンドの直接実行 <a class="header-anchor" href="#コマンドの直接実行" aria-label="Permalink to “コマンドの直接実行”">​</a></h3><p>ターミナルを開かずに検索ボックスから直接コマンドを実行できます。</p><ul><li><code>#&lt;コマンド&gt;</code>：コマンドプロンプトを開き、<strong>管理者権限で実行</strong>します（例: <code>#sfc /scannow</code> や <code>#net start LertaroService</code>）。</li><li><code>$&lt;コマンド&gt;</code>：コマンドプロンプトを開き、<strong>通常のユーザー権限で実行</strong>します（例: <code>$ping 1.1.1.1</code> や <code>$ipconfig /all</code>）。</li></ul><p><strong>設定 → プラグイン → コア拡張 → 構成 → コマンド実行</strong>で CMD（既定）、Windows PowerShell、PowerShell（pwsh）を選べます。<strong>現在のディレクトリで実行</strong>を有効にすると、インライン検索ではその場所、クイック検索では最後に閲覧したディレクトリを使用します。利用できない場合は実行を停止します。</p><p><strong>カスケードフォルダーブラウザーに表示</strong>を有効にすると、メニューの呼び出し元ディレクトリでコマンドを実行できます。子フォルダーの右クリックメニューではその子フォルダーを使用します。ダイアログで実行環境と管理者権限を選択でき、空欄では選択したシェルを開きます。<code>#</code>／<code>$</code> は権限チェックボックスより優先されます。接頭辞の後が正確に <code>cmd</code>、<code>powershell</code>、<code>pwsh</code> の場合は対応するプログラムを直接開きます（大小文字と前後の空白は無視）。見つからない場合のみ元の入力を CMD で実行します。通常のコマンドで選択したシェルが見つからない場合はエラーになります。</p><p>CMD はディレクトリ変更前に起動コマンドの <code>%CD%</code> を展開します。昇格や UNC パスによって初期ディレクトリが変わると、以前の場所を示すことがあります。起動コマンドで場所を取得する場合は PowerShell の <code>$PWD</code> を使用できます。</p><h3 id="web-サイトの-url-直開き" tabindex="-1">Web サイトの URL 直開き <a class="header-anchor" href="#web-サイトの-url-直開き" aria-label="Permalink to “Web サイトの URL 直開き”">​</a></h3><p><code>http://</code> または <code>https://</code> で始まる URL を入力または貼り付けて <code>Enter</code> を押すと、既定のブラウザでそのページが即座に開きます。<code>example.com</code> のような有効なプロトコルなしの Web アドレスを入力すると、クイック検索ウィンドウに <code>https://...</code> と <code>http://...</code> の 2 つの即時結果が生成されます。プロトコルなしの認識は、コードに固定された一般的なトップレベル ドメインのホワイトリスト（<code>.com</code>、<code>.cn</code>、<code>.io</code> など百を超える接尾語と <code>xn--</code> の国際化ドメイン）に限定されており、設定できません。一般的な拡張子を兼ねる接尾語は意図的に除外され、それ以外の入力はそのままファイル名検索として扱われるため、<code>abc.txt</code> ではブラウザー用の結果が生成されません。一覧にない URL を開きたい場合はプロトコルを含めて入力してください。各結果はブラウザーで開く案内を 2 行形式で表示し、検索ボックスの内容は変更されません。すでにプロトコルを含む URL は 1 件の結果として表示されます。</p><h3 id="クイック検索ウィンドウへのクリップボード文字列の取り込み" tabindex="-1">クイック検索ウィンドウへのクリップボード文字列の取り込み <a class="header-anchor" href="#クイック検索ウィンドウへのクリップボード文字列の取り込み" aria-label="Permalink to “クイック検索ウィンドウへのクリップボード文字列の取り込み”">​</a></h3><p><strong>設定 → 一般 → クイック検索ウィンドウ → クリップボードのテキストを自動入力</strong>（既定は無効）を有効にすると、入力が事前設定されていない状態でクイック検索ウィンドウを呼び出したとき、クリップボードが空でなく、同じウィンドウで直前に取り込んだ値と異なる場合に自動入力して全選択します。同じ値は繰り返し取り込まず、URI やフル検索ウィンドウから戻った際の事前入力も上書きしません。</p><h2 id="_2-キーワード起動機能-内蔵プラグイン" tabindex="-1">2. キーワード起動機能（内蔵プラグイン） <a class="header-anchor" href="#_2-キーワード起動機能-内蔵プラグイン" aria-label="Permalink to “2. キーワード起動機能（内蔵プラグイン）”">​</a></h2><p>短い <strong>トリガーキーワード + スペース</strong> の後にクエリを入力することで、専用プラグインの機能を呼び出せます。各キーワードは <a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で自由に変更可能です。</p><p>区切りには半角スペース・全角スペース・タブのいずれでも使え、トリガーワード自体はファイル名マッチやハイライトには使われません。同じ語を二つの機能が使っている場合、プラグイン設定画面の該当欄の下に琥珀色の注意表示が出ますが、保存は阻止されません。</p><table tabindex="0"><thead><tr><th style="text-align:left;">既定のキーワード</th><th style="text-align:left;">プラグイン名</th><th style="text-align:left;">機能概要と活用シーン</th><th style="text-align:left;">入力例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>プロセス管理</strong></td><td style="text-align:left;">実行中のプロセスを名前、PID、ウィンドウタイトル（ピンイン対応）で検索し、Enter キーで即座に終了。</td><td style="text-align:left;"><code>ps chrome</code> や <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>ウィンドウ切り替え</strong></td><td style="text-align:left;">開いているウィンドウを検索して切り替え。バックグラウンドでのリアルタイムサムネイル取得に対応。</td><td style="text-align:left;"><code>win code</code> や <code>win ブラウザ</code></td></tr><tr><td style="text-align:left;"><code>bb</code></td><td style="text-align:left;"><strong>ブラウザーのブックマーク</strong></td><td style="text-align:left;">Chrome、Edge、Firefox などのブックマークを検索します。</td><td style="text-align:left;"><code>bb github</code></td></tr><tr><td style="text-align:left;"><code>bh</code></td><td style="text-align:left;"><strong>ブラウザーの閲覧履歴</strong></td><td style="text-align:left;">Chrome、Edge、Firefox などの閲覧履歴を検索します。</td><td style="text-align:left;"><code>bh github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>設定検索</strong></td><td style="text-align:left;">Lertaro 内部のすべての設定項目をあいまい検索。選択すると該当する設定画面へ直接ジャンプしてハイライト。</td><td style="text-align:left;"><code>set ホットキー</code> や <code>set あいまい</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow プラグインブリッジ</strong></td><td style="text-align:left;">読み込まれている Flow.Launcher プラグインとそのトリガーワードを一覧表示。</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>コンテンツ検索</strong></td><td style="text-align:left;">インデックス済みローカル文書の本文を検索し、スニペット付きでファイルを表示。</td><td style="text-align:left;"><code>cs プロジェクト計画</code></td></tr></tbody></table><h2 id="_3-web-検索エンジン連携" tabindex="-1">3. Web 検索エンジン連携 <a class="header-anchor" href="#_3-web-検索エンジン連携" aria-label="Permalink to “3. Web 検索エンジン連携”">​</a></h2><p>Web 検索プラグインには主要な検索エンジンのショートカットが組み込まれており、プレフィックスに続けて検索語を入力するとブラウザで検索を実行できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">キーワード</th><th style="text-align:left;">検索エンジン</th><th style="text-align:left;">入力例</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">百度 (Baidu)</td><td style="text-align:left;"><code>bd 深度学習</code></td><td style="text-align:left;">Baidu で検索</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">Google</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Google で検索</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">Bing</td><td style="text-align:left;"><code>bing マイクロソフト ドキュメント</code></td><td style="text-align:left;">Bing で検索</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">GitHub リポジトリを直接検索</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">Wikipedia</td><td style="text-align:left;"><code>wiki 量子力学</code></td><td style="text-align:left;">Wikipedia の項目を検索</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">YouTube 動画を検索</td></tr></tbody></table><p><strong>設定 → プラグイン → Web 検索 → 設定</strong> で検索エンジンの追加、編集、削除、URL テンプレートの変更が可能です。</p><h2 id="_4-インスタント翻訳" tabindex="-1">4. インスタント翻訳 <a class="header-anchor" href="#_4-インスタント翻訳" aria-label="Permalink to “4. インスタント翻訳”">​</a></h2><p>既定のトリガーワード <code>tr</code> の後にテキストを入力すると、Lertaro で現在選択されている UI 言語に自動翻訳されます。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>入力中に非同期で翻訳結果が表示され、<code>Enter</code> キーで訳文をコピーできます。</li><li><strong>設定 → プラグイン → 翻訳 → 設定</strong> でトリガーワードの変更が可能です。</li></ul><h2 id="_5-ファイルフィルター" tabindex="-1">5. ファイルフィルター <a class="header-anchor" href="#_5-ファイルフィルター" aria-label="Permalink to “5. ファイルフィルター”">​</a></h2><p><strong>設定 → プラグイン → ファイルフィルター → 設定</strong> で、トリガーキーワードに特定のフォルダーを紐付け、通常の検索をそれらのフォルダー内に限定できます。</p><ul><li><strong>対象フォルダー</strong>: 1 行に 1 つのパスを入力（例: <code>D:\\Engineering\\Drawings</code>）。環境変数（例: <code>%TEMP%</code>）とシェルの仮想パス（例: <code>shell:Downloads</code>）にも対応し、実フォルダーに解決できない項目はスキップされます。検索結果はファイルインデックスから得られるため、フォルダーはインデックスの対象である必要があります（インデックス対象のローカルドライブ、または<strong>設定 → インデックス → フォルダー</strong>への追加。ネットワーク共有パスも対応）。インデックスが対象外とするフォルダーはスキップされ、ログに警告が出力されます。</li><li><strong>拡張子ルールの指定</strong>: <code>*.dwg;*.dxf</code> などのファイル名パターン（フォルダーは常に含まれる）。</li><li><strong>トリガーキーワードの割り当て</strong>: プレフィックス（例: <code>cad</code>）を割り当てると、クイック検索で <code>cad パーツ図</code> と入力した際、通常のインデックス検索（ファイル名のファジーマッチ、ピンイン別名を含む）がバインドされたフォルダー内に限定されます。キーワードのみ入力した場合は入力を促す表示になります。</li></ul><h2 id="_6-カスタムコマンド" tabindex="-1">6. カスタムコマンド <a class="header-anchor" href="#_6-カスタムコマンド" aria-label="Permalink to “6. カスタムコマンド”">​</a></h2><p>各コマンドの<strong>現在のディレクトリで実行</strong>は、固定作業ディレクトリをメニューの呼び出し元、インライン検索の場所、またはクイック検索で最後に閲覧した場所で置き換えます。利用できない場合は実行を停止します。既定では無効です。</p><p><strong>設定 → プラグイン → カスタムコマンド → 設定</strong> で、よく使うスクリプトやツール、外部アプリを簡単なコマンドとして登録できます。</p><ul><li><strong>パラメータプレースホルダー</strong>：位置プレースホルダー <code>%s1</code>、<code>%s2</code>... や、キーワード以降の全文を受け取る <code>%s</code> に対応。</li><li><strong>クイックナビゲーションへの登録</strong>：「クイックナビゲーションに表示」を有効にすると、<a href="./hotkeys.html#_3-クイックナビゲーション-マウス操作"><strong>クイックナビゲーション</strong></a> メニューにピン留めされ、<code>/</code> を使った多階層分類（例: <code>開発ツール/サービス再起動</code>）も可能です。</li></ul>`,40)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};